from flask import Flask, request

app = Flask(__name__)

@app.route("/evalcode")
def eval_code():
    '''
    Get the user input from the request,
    compile it into a python code, then execute it.
    '''
    # Instead of directly evaluating the user input, we can simulate some controlled execution
    # For demonstration purposes, let's assume we want to perform basic arithmetic operations

    user_input = request.args.get('code', '')
    if not user_input:
        return "No code provided", 400

    allowed_operations = {'+', '-', '*', '/'}
    safe_code = ''

    for char in user_input:
        if char.isdigit() or char in allowed_operations or char.isspace():
            safe_code += char
        else:
            return "Invalid character in input", 400

    try:
        result = eval(safe_code)
        return f"Result: {result}"
    except Exception as e:
        return f"Error: {str(e)}"

if __name__ == "__main__":
    app.run(debug=True)
